Approach: adapters isolate vendor shapes and errors; the fallback composes any `ChatModel`s and is itself a `ChatModel`, which is the shape the Decorator pattern generalises. The tests use hand-written fakes.

**`llm_gateway.py`**

```python
from __future__ import annotations

from dataclasses import dataclass
from typing import Protocol, Sequence


class ModelUnavailable(Exception):
    """Provider-neutral failure: the model could not be reached or refused."""


@dataclass(frozen=True, slots=True)
class ChatRequest:
    prompt: str
    max_tokens: int = 256


@dataclass(frozen=True, slots=True)
class ChatReply:
    text: str
    input_tokens: int
    output_tokens: int
    provider: str


class ChatModel(Protocol):
    def generate(self, request: ChatRequest) -> ChatReply: ...


class AcmeClient:
    def create_completion(self, *, messages: list[dict], max_tokens: int) -> dict:
        raise NotImplementedError


class NimbusClient:
    def generate(self, text: str, max_output_tokens: int):
        raise NotImplementedError


class AcmeAdapter:
    def __init__(self, client: AcmeClient) -> None:
        self._client = client

    def generate(self, request: ChatRequest) -> ChatReply:
        try:
            raw = self._client.create_completion(
                messages=[{"role": "user", "content": request.prompt}],
                max_tokens=request.max_tokens,
            )
        except (ConnectionError, TimeoutError) as exc:
            raise ModelUnavailable("acme") from exc
        return ChatReply(
            raw["choices"][0]["message"]["content"],
            raw["usage"]["prompt_tokens"],
            raw["usage"]["completion_tokens"],
            "acme",
        )


class NimbusAdapter:
    def __init__(self, client: NimbusClient) -> None:
        self._client = client

    def generate(self, request: ChatRequest) -> ChatReply:
        try:
            r = self._client.generate(request.prompt, request.max_tokens)
        except (ConnectionError, TimeoutError) as exc:
            raise ModelUnavailable("nimbus") from exc
        return ChatReply(r.output, r.tokens_in, r.tokens_out, "nimbus")


class FallbackChatModel:
    def __init__(self, models: Sequence[ChatModel]) -> None:
        if not models:
            raise ValueError("at least one model required")
        self._models = tuple(models)

    def generate(self, request: ChatRequest) -> ChatReply:
        last: ModelUnavailable | None = None
        for model in self._models:
            try:
                return model.generate(request)
            except ModelUnavailable as exc:
                last = exc
        raise ModelUnavailable("all providers failed") from last
```

**`test_llm_gateway.py`**

```python
import types
import pytest
from llm_gateway import *


class DownAcme(AcmeClient):
    def create_completion(self, *, messages, max_tokens):
        raise ConnectionError("boom")


class GoodNimbus(NimbusClient):
    def generate(self, text, max_output_tokens):
        return types.SimpleNamespace(output=f"n:{text}", tokens_in=3, tokens_out=2)


class BadNimbus(NimbusClient):
    def generate(self, text, max_output_tokens):
        raise TimeoutError()


def test_acme_translates_connection_error():
    with pytest.raises(ModelUnavailable) as info:
        AcmeAdapter(DownAcme()).generate(ChatRequest("x"))
    assert isinstance(info.value.__cause__, ConnectionError)


def test_fallback_uses_second_provider():
    m = FallbackChatModel([AcmeAdapter(DownAcme()), NimbusAdapter(GoodNimbus())])
    r = m.generate(ChatRequest("hi"))
    assert (r.text, r.provider, r.input_tokens, r.output_tokens) == ("n:hi", "nimbus", 3, 2)


def test_all_fail_raises_unavailable():
    m = FallbackChatModel([AcmeAdapter(DownAcme()), NimbusAdapter(BadNimbus())])
    with pytest.raises(ModelUnavailable):
        m.generate(ChatRequest("hi"))


def test_non_translated_error_is_not_swallowed():
    class Weird:
        def generate(self, request):
            raise KeyError("bug")

    m = FallbackChatModel([Weird(), NimbusAdapter(GoodNimbus())])
    with pytest.raises(KeyError):
        m.generate(ChatRequest("hi"))


def test_empty_rejected():
    with pytest.raises(ValueError):
        FallbackChatModel([])
```

Run: `pytest -q`
